menu = {1: ("콜라", 1200), 2: ("물", 800), 3: ("주스", 1500)}
money = int(input())

while True:
    number = int(input())
    if number == 0:
        break
    if number not in menu:
        print("없는 상품")
        continue
    name, price = menu[number]
    if price > money:
        print("잔액 부족")
    else:
        money -= price
        print(f"{name} 구매")

print(f"거스름돈: {money}원")
